import sys
from bisect import bisect_left, bisect_right
from array import array


class FenwickRangeMax:
    def __init__(self, points, prefix_mode):
        self.prefix_mode = prefix_mode
        max_coord = 1
        for x, _ in points:
            if x + 1 > max_coord:
                max_coord = x + 1
        size = 1
        while size < max_coord:
            size <<= 1
        self.size = size

        coords = [[] for _ in range(2 * size)]
        for x, y in points:
            p = x + size
            while p:
                coords[p].append(y)
                p >>= 1

        self.coords = coords
        self.bits = [None] * (2 * size)

        for i in range(2 * size):
            if coords[i]:
                coords[i] = sorted(set(coords[i]))
                self.bits[i] = array('i', [0]) * (len(coords[i]) + 1)

    def update(self, x, y, value):
        p = x + self.size
        while p:
            ys = self.coords[p]
            pos = bisect_left(ys, y)
            bit = self.bits[p]

            if self.prefix_mode:
                k = pos + 1
            else:
                k = len(ys) - pos

            while k < len(bit):
                if bit[k] < value:
                    bit[k] = value
                k += k & -k

            p >>= 1

    def _node_query(self, node, threshold):
        ys = self.coords[node]
        bit = self.bits[node]

        if self.prefix_mode:
            k = bisect_right(ys, threshold)
        else:
            k = len(ys) - bisect_left(ys, threshold)

        ans = 0
        while k:
            if bit[k] > ans:
                ans = bit[k]
            k -= k & -k
        return ans

    def query(self, left, right, threshold):
        if left > right:
            return 0

        left += self.size
        right += self.size + 1
        ans = 0

        while left < right:
            if left & 1:
                v = self._node_query(left, threshold)
                if v > ans:
                    ans = v
                left += 1
            if right & 1:
                right -= 1
                v = self._node_query(right, threshold)
                if v > ans:
                    ans = v
            left >>= 1
            right >>= 1

        return ans


def main():
    input = sys.stdin.buffer.readline
    N, M, Q = map(int, input().split())

    intervals = []
    for _ in range(M):
        s, t = map(int, input().split())
        a = min(s, t) - 1
        b = max(s, t) - 1
        intervals.append((a, b))

    # Structure 1:
    # point (a, b), query a-range and b >= threshold.
    points1 = intervals

    # Structure 2:
    # point (b, a), query b-range and a <= threshold.
    points2 = [(b, a) for a, b in intervals]

    st1 = FenwickRangeMax(points1, prefix_mode=False)
    st2 = FenwickRangeMax(points2, prefix_mode=True)

    # For equal left/right endpoints, only the latest interval with
    # a different opposite endpoint is relevant.
    left_best = {}
    right_best = {}

    bad = [0] * (M + 1)

    for idx, (a, b) in enumerate(intervals, 1):
        conflict = 0

        # Crossing:
        # a < c < b < d
        v = st1.query(a + 1, b - 1, b + 1)
        if v > conflict:
            conflict = v

        # Crossing:
        # c < a < d < b
        v = st2.query(a + 1, b - 1, a - 1)
        if v > conflict:
            conflict = v

        # Same left endpoint, different right endpoint.
        entry = left_best.get(a)
        if entry is not None:
            if entry[1] != b and entry[0] > conflict:
                conflict = entry[0]

        # Same right endpoint, different left endpoint.
        entry = right_best.get(b)
        if entry is not None:
            if entry[1] != a and entry[0] > conflict:
                conflict = entry[0]

        bad[idx] = conflict

        old = left_best.get(a)
        if old is None or idx > old[0]:
            left_best[a] = (idx, b)

        old = right_best.get(b)
        if old is None or idx > old[0]:
            right_best[b] = (idx, a)

        st1.update(a, b, idx)
        st2.update(b, a, idx)

    # Range maximum of bad[r].
    size = 1
    while size < M + 1:
        size <<= 1
    seg = [0] * (2 * size)
    for i in range(1, M + 1):
        seg[size + i] = bad[i]
    for i in range(size - 1, 0, -1):
        seg[i] = max(seg[i << 1], seg[i << 1 | 1])

    def range_max(left, right):
        left += size
        right += size + 1
        ans = 0
        while left < right:
            if left & 1:
                ans = max(ans, seg[left])
                left += 1
            if right & 1:
                right -= 1
                ans = max(ans, seg[right])
            left >>= 1
            right >>= 1
        return ans

    out = []
    for _ in range(Q):
        l, r = map(int, input().split())
        out.append("Yes" if range_max(l, r) < l else "No")

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()

import sys


def solve():
    input = sys.stdin.buffer.readline
    t = int(input())
    out = []

    LIMIT = 12

    for _ in range(t):
        n, k = map(int, input().split())
        cakes = []
        for i in range(n):
            x, y, z = map(int, input().split())
            vals = (x, y, z)
            m = max(vals)
            c = 1 << vals.index(m)
            cakes.append((vals, m, c, i))

        cakes.sort(key=lambda item: item[1], reverse=True)
        selected = cakes[:2 * k]
        outside = cakes[2 * k:]

        base_value = sum(item[1] for item in selected)
        parity = 0
        for _, _, c, _ in selected:
            parity ^= c

        if parity == 0:
            out.append(str(base_value))
            continue

        atoms = {3: [], 5: [], 6: []}

        # Changing the assigned coordinate of one selected cake.
        for vals, m, c, idx in selected:
            for d in range(3):
                nd = 1 << d
                if nd == c:
                    continue
                loss = m - vals[d]
                delta = c ^ nd
                atoms[delta].append((loss, (idx,)))

        # Replacing one selected cake by one unselected cake.
        selected_by_color = {1: [], 2: [], 4: []}
        outside_by_color = {1: [], 2: [], 4: []}

        for vals, m, c, idx in selected:
            selected_by_color[c].append((m, idx))
        for vals, m, c, idx in outside:
            for d in range(3):
                outside_by_color[1 << d].append((vals[d], idx))

        for c in (1, 2, 4):
            selected_by_color[c].sort(reverse=True)
            selected_by_color[c] = selected_by_color[c][:LIMIT]

        for d in (1, 2, 4):
            outside_by_color[d].sort(reverse=True)
            outside_by_color[d] = outside_by_color[d][:LIMIT]

        for c in (1, 2, 4):
            for d in (1, 2, 4):
                delta = c ^ d
                if delta == 0:
                    continue
                for sm, si in selected_by_color[c]:
                    for ov, oi in outside_by_color[d]:
                        atoms[delta].append((sm - ov, (si, oi)))

        for mask in atoms:
            atoms[mask].sort(key=lambda x: x[0])
            atoms[mask] = atoms[mask][:LIMIT * LIMIT]

        best_loss = 10**30

        for mask in (3, 5, 6):
            if mask == parity:
                for loss, _ in atoms[mask]:
                    if loss < best_loss:
                        best_loss = loss

        for m1 in (3, 5, 6):
            m2 = parity ^ m1
            if m2 not in atoms:
                continue
            for loss1, ids1 in atoms[m1]:
                s1 = set(ids1)
                for loss2, ids2 in atoms[m2]:
                    if s1.isdisjoint(ids2):
                        loss = loss1 + loss2
                        if loss < best_loss:
                            best_loss = loss
                        break

        out.append(str(base_value - best_loss))

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    solve()

