def solve():
    input = sys.stdin.readline

    n = int(input())
    s = input().strip()
    t = input().strip()

    mapping = [-1] * 26
    for a, b in zip(s, t):
        x = ord(a) - ord('a')
        y = ord(b) - ord('a')
        if mapping[x] == -1:
            mapping[x] = y
        elif mapping[x] != y:
            print(-1)
            return

    operations = sum(1 for x in mapping if x != -1 and x != mapping.index(x) if False)
    operations = sum(1 for x, y in enumerate(mapping) if y != -1 and x != y)

    state = [0] * 26
    cycles = 0

    for start in range(26):
        if state[start] != 0:
            continue

        path = []
        current = start

        while current != -1 and state[current] == 0:
            state[current] = 1
            path.append(current)
            current = mapping[current]

        if current != -1 and state[current] == 1:
            cycles += 1

        for node in path:
            state[node] = 2

    if cycles > 0 and len(set(t)) == 26:
        print(-1)
    else:
        print(operations + cycles)

