import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    t = data[0]
    ptr = 1
    answers = []

    for _ in range(t):
        n = data[ptr]
        ptr += 1
        a = data[ptr:ptr + n]
        ptr += n

        runs = 0
        internal_savings = 0
        prev = None

        for x in a:
            if x == prev:
                internal_savings += 1
            else:
                runs += 1
                prev = x

        extra_savings = 0
        seen = set()

        for x in a:
            if x == prev:
                continue
            # handled below using the compressed sequence
        compressed = []
        prev = None
        for x in a:
            if x != prev:
                compressed.append(x)
                prev = x

        seen.clear()
        for x in compressed:
            if x in seen:
                extra_savings += 1
                seen.clear()
            else:
                seen.add(x)

        answers.append(str(n - internal_savings - extra_savings))

    sys.stdout.write("\n".join(answers))


