    solve()

from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def prefix(n: int) -> int:
            if n <= 0:
                return 0

            total = 0
            start = 1
            steps = 1

            while start <= n:
                end = min(n, start * 4 - 1)
                total += (end - start + 1) * steps
                start *= 4
                steps += 1

            return total

        answer = 0

        for l, r in queries:
            required = prefix(r) - prefix(l - 1)
            answer += (required + 1) // 2

        return answer

import sys

def solve():
    s = sys.stdin.buffer.readline().strip()
    n = len(s)
    rev = s[::-1]

    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        while j and rev[i] != rev[j]:
            j = pi[j - 1]
        if rev[i] == rev[j]:
            j += 1
        pi[i] = j

    j = 0
    for c in s:
        while j and c != rev[j]:
            j = pi[j - 1]
        if c == rev[j]:
            j += 1

    answer = s + s[:n - j][::-1]
    sys.stdout.buffer.write(answer + b"\n")

