from functools import lru_cache


class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        DIGITS = 9
        POW9 = [1] * (DIGITS + 1)
        for i in range(1, DIGITS + 1):
            POW9[i] = POW9[i - 1] * 9

        # Number of positive integers <= n whose decimal representation
        # contains no zero digit.
        def count_no_zero(n: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n).zfill(DIGITS)))
            false_count = [0] * (DIGITS + 1)
            for k in range(1, DIGITS + 1):
                false_count[k] = false_count[k - 1] + POW9[k]

            result = 0
            started = False

            for pos, limit in enumerate(digits):
                remaining = DIGITS - pos - 1

                if not started:
                    if limit > 0:
                        # Choose 0 and remain before the first nonzero digit.
                        result += false_count[remaining]
                        # Choose a nonzero digit smaller than limit.
                        result += (limit - 1) * POW9[remaining]
                else:
                    # Once started, zero is not allowed.
                    if limit > 1:
                        result += (limit - 1) * POW9[remaining]

                if not started:
                    if limit == 0:
                        continue
                    started = True
                else:
                    if limit == 0:
                        break

            else:
                if started:
                    result += 1

            return result

        # Count zero-free beautiful numbers <= n.
        def count_valid_no_zero(n: int, target_sum: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n).zfill(DIGITS)))
            initial_product = 1 % target_sum

            @lru_cache(None)
            def free(pos: int, remaining_sum: int, product: int,
                     started: bool) -> int:
                left = DIGITS - pos

                if remaining_sum < 0 or remaining_sum > 9 * left:
                    return 0
                if started and remaining_sum < left:
                    return 0

                if pos == DIGITS:
                    return int(
                        started and remaining_sum == 0 and product == 0
                    )

                answer = 0

                if not started:
                    # Leading zero: still before the first actual digit.
                    answer += free(
                        pos + 1,
                        remaining_sum,
                        product,
                        False
                    )

                    for digit in range(1, 10):
                        answer += free(
                            pos + 1,
                            remaining_sum - digit,
                            digit % target_sum,
                            True
                        )
                else:
                    for digit in range(1, 10):
                        answer += free(
                            pos + 1,
                            remaining_sum - digit,
                            (product * digit) % target_sum,
                            True
                        )

                return answer

            answer = 0
            remaining_sum = target_sum
            product = initial_product
            started = False

            for pos, limit in enumerate(digits):
                for digit in range(limit):
                    if not started:
                        if digit == 0:
                            next_started = False
                            next_product = product
                        else:
                            next_started = True
                            next_product = digit % target_sum
                    else:
                        if digit == 0:
                            continue
                        next_started = True
                        next_product = (product * digit) % target_sum

                    answer += free(
                        pos + 1,
                        remaining_sum - digit,
                        next_product,
                        next_started
                    )

                if not started:
                    if limit == 0:
                        continue
                    started = True
                    product = limit % target_sum
                else:
                    if limit == 0:
                        break
                    product = (product * limit) % target_sum

                remaining_sum -= limit
                if remaining_sum < 0:
                    break
            else:
                if started and remaining_sum == 0 and product == 0:
                    answer += 1

            return answer

        def beautiful_up_to(n: int) -> int:
            if n <= 0:
                return 0

            no_zero = count_no_zero(n)
            valid_no_zero = 0

            for digit_sum in range(1, 9 * DIGITS + 1):
                valid_no_zero += count_valid_no_zero(n, digit_sum)

            # Every positive number containing a zero digit is beautiful,
            # since its digit product is zero.
            return n - no_zero + valid_no_zero

        return beautiful_up_to(r) - beautiful_up_to(l - 1)

