import math

def solve():
    n = int(sys.stdin.readline())

    d = 1  # d = x - y
    while d * d * d <= n:
        if n % d == 0:
            q = n // d
            disc = 12 * q - 3 * d * d

            if disc >= 0:
                root = math.isqrt(disc)
                if root * root == disc:
                    numerator = root - 3 * d
                    if numerator > 0 and numerator % 6 == 0:
                        y = numerator // 6
                        x = y + d
                        if x > y > 0 and x * x * x - y * y * y == n:
                            print(x, y)
                            return
        d += 1

    print(-1)

