import sys
from collections import deque


class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        self.g[fr].append([to, cap, len(self.g[to])])
        self.g[to].append([fr, 0, len(self.g[fr]) - 1])

    def max_flow(self, s, t, limit):
        flow = 0
        INF = 10**9

        while flow < limit:
            level = [-1] * self.n
            level[s] = 0
            q = deque([s])

            while q:
                v = q.popleft()
                for to, cap, rev in self.g[v]:
                    if cap > 0 and level[to] < 0:
                        level[to] = level[v] + 1
                        q.append(to)

            if level[t] < 0:
                break

            it = [0] * self.n

            def dfs(v, f):
                if v == t:
                    return f

                while it[v] < len(self.g[v]):
                    i = it[v]
                    to, cap, rev = self.g[v][i]

                    if cap > 0 and level[v] < level[to]:
                        pushed = dfs(to, min(f, cap))
                        if pushed:
                            self.g[v][i][1] -= pushed
                            self.g[to][rev][1] += pushed
                            return pushed

                    it[v] += 1

                return 0

            while flow < limit:
                pushed = dfs(s, min(INF, limit - flow))
                if pushed == 0:
                    break
                flow += pushed

        return flow


def required_edges(n, edges, d, limit):
    if d == 0:
        return 0

    layers = n * d
    source = layers
    sink = layers + 1
    dinic = Dinic(layers + 2)
    INF = 10**9

    def node(v, level):
        return (v - 1) * d + (level - 1)

    # Force label(1) = 0 and label(N) >= d.
    dinic.add_edge(node(1, 1), sink, INF)
    dinic.add_edge(source, node(n, d), INF)

    # Labels must be non-increasing when moving from level j to j+1.
    for v in range(1, n + 1):
        for j in range(1, d):
            dinic.add_edge(node(v, j + 1), node(v, j), INF)

    for u, v in edges:
        # Cost 1 when label(v) is exactly one greater than label(u).
        for j in range(1, d + 1):
            dinic.add_edge(node(v, j), node(u, j), 1)

        # Along every edge, the label can increase by at most one.
        for j in range(1, d):
            dinic.add_edge(node(v, j + 1), node(u, j), INF)

    return dinic.max_flow(source, sink, limit)


def main():
    input = sys.stdin.readline
    n, m, k = map(int, input().split())
    edges = [tuple(map(int, input().split())) for _ in range(m)]

    lo, hi = 0, n  # answer is at most N-1

    while hi - lo > 1:
        mid = (lo + hi) // 2
        if required_edges(n, edges, mid, k + 1) <= k:
            lo = mid
        else:
            hi = mid

    print(lo)


if __name__ == "__main__":
    main()

import sys


def has_pair(mask_a, mask_b, target):
    """Whether there exist x in mask_a and y in mask_b with x + y = target."""
    if mask_a.bit_count() > mask_b.bit_count():
        mask_a, mask_b = mask_b, mask_a

    x = mask_a
    while x:
        low = x & -x
        value = low.bit_length() - 1
        other = target - value
        if other >= 0 and ((mask_b >> other) & 1):
            return True
        x ^= low
    return False


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, k = data[0], data[1]
    vcnt = n * k
    graph = [[] for _ in range(vcnt)]

    pos = 2
    for _ in range(vcnt - 1):
        u = data[pos] - 1
        v = data[pos + 1] - 1
        pos += 2
        graph[u].append(v)
        graph[v].append(u)

    parent = [-1] * vcnt
    order = [0]
    parent[0] = vcnt
    for v in order:
        for to in graph[v]:
            if to != parent[v]:
                parent[to] = v
                order.append(to)

    valid = [False] * vcnt
    residual = [0] * vcnt

    target = k - 1
    limit = (1 << k) - 1

    for v in reversed(order):
        mandatory = []
        optional_masks = []
        possible = True

        for to in graph[v]:
            if parent[to] != v:
                continue

            if valid[to]:
                if residual[to]:
                    optional_masks.append(residual[to])
            else:
                if residual[to] == 0:
                    possible = False
                    break
                mandatory.append(residual[to])

        if not possible or len(mandatory) > 2:
            valid[v] = False
            residual[v] = 0
            continue

        m = len(mandatory)
        is_valid = False
        rem_mask = 0

        if m == 0:
            if k == 1:
                is_valid = True

            union_optional = 0
            for mask in optional_masks:
                shifted = (mask << 1) & limit
                rem_mask |= shifted

                if not is_valid and union_optional:
                    if has_pair(mask, union_optional, target):
                        is_valid = True

                union_optional |= mask

        elif m == 1:
            base = mandatory[0]

            # Connect the vertex to the mandatory residual path only.
            if (base >> (k - 1)) & 1:
                is_valid = True

            # Connect one mandatory and one optional residual path.
            if optional_masks:
                union_optional = 0
                for mask in optional_masks:
                    union_optional |= mask
                needed_mask = 0
                x = base
                while x:
                    low = x & -x
                    value = low.bit_length() - 1
                    other = target - value
                    if other >= 0:
                        needed_mask |= 1 << other
                    x ^= low
                if union_optional & needed_mask:
                    is_valid = True

            rem_mask = (base << 1) & limit

        else:
            # Both mandatory residual paths must be joined through v.
            if has_pair(mandatory[0], mandatory[1], target):
                is_valid = True

        valid[v] = is_valid
        residual[v] = rem_mask

    print("Yes" if valid[0] else "No")


if __name__ == "__main__":
    solve()

from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events = [[] for _ in range(n + 1)]

        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            events[b].append((a, idx))

        gains = [0] * len(conflictingPairs)
        total = 0

        top_value = 0
        top_id = -1
        second_value = 0
        second_id = -1

        for right in range(1, n + 1):
            for left, pair_id in events[right]:
                if left >= top_value:
                    second_value = top_value
                    second_id = top_id
                    top_value = left
                    top_id = pair_id
                elif left > second_value:
                    second_value = left
                    second_id = pair_id

            total += right - top_value

            if top_id != -1:
                gains[top_id] += top_value - second_value

        return total + max(gains)

