        graph[y].append((x, z))

    dist = [-1] * n
    answer = [0] * n
    bit_count = 30

    for start in range(n):
        if dist[start] != -1:
            continue

        dist[start] = 0
        queue = deque([start])
        component = []

        while queue:
            u = queue.popleft()
            component.append(u)

            for v, z in graph[u]:
                expected = dist[u] ^ z
                if dist[v] == -1:
                    dist[v] = expected
                    queue.append(v)
                elif dist[v] != expected:
                    print(-1)
                    return

        size = len(component)
        ones = [0] * bit_count

        for v in component:
            value = dist[v]
            for bit in range(bit_count):
                ones[bit] += (value >> bit) & 1

        shift = 0
        for bit in range(bit_count):
            if ones[bit] > size - ones[bit]:
                shift |= 1 << bit

        for v in component:
            answer[v] = dist[v] ^ shift

    print(*answer)

