class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        total = n + m - 1

        # Prefix function for KMP.
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and str2[i] != str2[j]:
                j = pi[j - 1]
            if str2[i] == str2[j]:
                j += 1
            pi[i] = j

        # KMP transitions. State is the current matched prefix length,
        # always in [0, m - 1]. An occurrence is represented by the
        # transition from state m-1 using str2[m-1].
        trans = [[0] * 26 for _ in range(m)]
        masks = [0] * m

        for state in range(m):
            mask = 0
            for c in range(26):
                ch = chr(ord('a') + c)
                k = state
                while k > 0 and str2[k] != ch:
                    k = pi[k - 1]
                if str2[k] == ch:
                    k += 1

                if k == m:
                    nxt = pi[m - 1]
                else:
                    nxt = k

                trans[state][c] = nxt
                mask |= 1 << nxt
            masks[state] = mask

        # For state m-1, exclude the character that completes an occurrence.
        last_char = ord(str2[-1]) - ord('a')
        no_event_mask = 0
        state = m - 1
        for c in range(26):
            if c != last_char:
                no_event_mask |= 1 << trans[state][c]

        all_states = (1 << m) - 1
        feasible = [0] * (total + 1)
        feasible[total] = all_states

        # feasible[p] contains states from which positions p..total-1
        # can be completed successfully.
        for p in range(total - 1, -1, -1):
            nxt_feasible = feasible[p + 1]

            if p < m - 1:
                row = 0
                for state in range(m):
                    if masks[state] & nxt_feasible:
                        row |= 1 << state
                feasible[p] = row
                continue

            constraint = str1[p - m + 1]

            if constraint == 'T':
                fallback = pi[m - 1]
                if nxt_feasible & (1 << fallback):
                    feasible[p] = 1 << (m - 1)
            else:
                row = 0
                for state in range(m - 1):
                    if masks[state] & nxt_feasible:
                        row |= 1 << state

                if no_event_mask & nxt_feasible:
                    row |= 1 << (m - 1)

                feasible[p] = row

        if not (feasible[0] & 1):
            return ""

        # Reconstruct the lexicographically smallest valid string.
        result = []
        state = 0

        for p in range(total):
            nxt_feasible = feasible[p + 1]

            if p < m - 1:
                required = 0  # no occurrence condition
            else:
                required = 1 if str1[p - m + 1] == 'T' else -1

            chosen = -1
            for c in range(26):
                is_event = (state == m - 1 and c == last_char)

                if required == 1 and not is_event:
                    continue
                if required == -1 and is_event:
                    continue

                nxt_state = trans[state][c]
                if nxt_feasible & (1 << nxt_state):
                    chosen = c
                    state = nxt_state
                    result.append(chr(ord('a') + c))
                    break

            if chosen == -1:
                return ""

        return ''.join(result)

from typing import List


class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        factorial = [1] * (n + 1)
        for i in range(1, n + 1):
            factorial[i] = factorial[i - 1] * i

        def count_completions(odd: int, even: int, next_parity: int) -> int:
            remaining = odd + even
            needed_odd = (remaining + 1) // 2 if next_parity == 1 else remaining // 2
            needed_even = remaining - needed_odd

            if odd != needed_odd or even != needed_even:
                return 0

            return factorial[odd] * factorial[even]

        used = [False] * (n + 1)
        result = []
        previous_parity = -1

        for _ in range(n):
            chosen = False

            for value in range(1, n + 1):
                if used[value]:
                    continue

                parity = value % 2
                if previous_parity != -1 and parity == previous_parity:
                    continue

                odd_remaining = (n + 1) // 2
                even_remaining = n // 2

                for selected in result:
                    if selected % 2 == 1:
                        odd_remaining -= 1
                    else:
                        even_remaining -= 1

                if parity == 1:
                    odd_remaining -= 1
                else:
                    even_remaining -= 1

                completions = count_completions(
                    odd_remaining,
                    even_remaining,
                    1 - parity
                )

                if k > completions:
                    k -= completions
                else:
                    result.append(value)
                    used[value] = True
                    previous_parity = parity
                    chosen = True
                    break

            if not chosen:
                return []

        return result

