MOD = 998244353


def make_transition(state, active, value):
    lo = [-1] * 4
    hi = [-1] * 4

    if not active:
        if value == 0:
            trans = ((0, 1, 0),)
        elif value == 1:
            trans = ((0, 0, 0), (1, 1, 0))
        else:
            trans = ((1, 0, 0),)
    else:
        if value == 0:
            trans = ((0, 1, 0),)
        elif value == 1:
            trans = ((0, 0, 0), (0, 1, 1), (1, 1, 0))
        elif value == 2:
            trans = ((0, 0, 0), (1, 0, 0), (1, 1, 1))
        else:
            trans = ((1, 0, 1),)

    for start in range(2):
        base = start * 2
        for old_end, new_end, cost in trans:
            idx = base + old_end
            l = state[idx * 2]
            if l < 0:
                continue
            h = state[idx * 2 + 1]
            target = base + new_end
            nl = l + cost
            nh = h + cost
            if lo[target] < 0 or nl < lo[target]:
                lo[target] = nl
            if nh > hi[target]:
                hi[target] = nh

    mn = min(x for x in lo if x >= 0)
    result = []
    for i in range(4):
        if lo[i] < 0:
            result.extend((-1, -1))
        else:
            result.extend((lo[i] - mn, hi[i] - mn))
    return tuple(result)


def interval_union_size(a, b, c, d):
    if a < 0:
        return 0 if c < 0 else d - c + 1
    if c < 0:
        return b - a + 1
    if a > c:
        a, b, c, d = c, d, a, b
    if c <= b + 1:
        return max(b, d) - a + 1
    return (b - a + 1) + (d - c + 1)


def solve():
    input = sys.stdin.buffer.readline
    n = int(input())
    s = input().strip()

    initial = (0, 0, -1, -1, -1, -1, 0, 0)
    dp = {initial: 1}

    cache = {}

    for ch in s:
        active = ch == ord('1')
        ndp = {}

        values = (0, 1, 2, 3) if active else (0, 1, 2)

        for state, count in dp.items():
            for value in values:
                key = (state, active, value)
                nxt = cache.get(key)
                if nxt is None:
                    nxt = make_transition(state, active, value)
                    cache[key] = nxt
                ndp[nxt] = (ndp.get(nxt, 0) + count) % MOD

        dp = ndp

    answer = 0
    for state, count in dp.items():
        a, b = state[0], state[1]
        c, d = state[6], state[7]
        ways = interval_union_size(a, b, c, d)
        answer = (answer + count * ways) % MOD

    print(answer)


