class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perimeter = 4 * side
        positions = []

        # Map each boundary point to its position on the perimeter.
        # Corners are assigned consistently to avoid duplicates.
        for x, y in points:
            if y == 0:
                t = x
            elif x == side:
                t = side + y
            elif y == side:
                t = 3 * side - x
            else:
                t = 4 * side - y
            positions.append(t)

        positions.sort()
        n = len(positions)
        doubled = positions + [x + perimeter for x in positions]

        def feasible(distance: int) -> bool:
            # next_index[i] is the first index j > i such that
            # doubled[j] - doubled[i] >= distance.
            next_index = [2 * n] * (2 * n)
            j = 1

            for i in range(2 * n):
                if j < i + 1:
                    j = i + 1
                target = doubled[i] + distance
                while j < 2 * n and doubled[j] < target:
                    j += 1
                next_index[i] = j

            # Try every point as the first selected point.
            for start in range(n):
                current = start
                valid = True

                for _ in range(k - 1):
                    current = next_index[current]
                    if current >= start + n:
                        valid = False
                        break

                if valid and doubled[start] + perimeter - doubled[current] >= distance:
                    return True

            return False

        low, high = 0, side + 1

        while low + 1 < high:
            mid = (low + high) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid

        return low

