def solve():
    input = sys.stdin.buffer.readline
    n = int(input())

    graph = [[] for _ in range(n)]
    for _ in range(n - 1):
        a, b = map(int, input().split())
        a -= 1
        b -= 1
        graph[a].append(b)
        graph[b].append(a)

    parent = [-2] * n
    parent[0] = -1
    order = [0]

    for v in order:
        for u in graph[v]:
            if parent[u] == -2:
                parent[u] = v
                order.append(u)

    down_total = [1] * n
    down_branch = [-1] * n

    for v in reversed(order):
        top = []
        child_count = 0

        for u in graph[v]:
            if parent[u] == v:
                child_count += 1
                top.append(down_total[u])

        top.sort(reverse=True)
        if child_count >= 3:
            branch = 1 + top[0] + top[1] + top[2]
            down_branch[v] = branch
            down_total[v] = branch
        else:
            down_total[v] = 1

    up_total = [-1] * n
    up_branch = [-1] * n
    answer = -1

    for v in order:
        incoming = []

        if parent[v] != -1:
            incoming.append((parent[v], up_total[v]))

        for u in graph[v]:
            if parent[u] == v:
                incoming.append((u, down_total[u]))

        top4 = sorted(incoming, key=lambda x: x[1], reverse=True)[:4]

        # Use v as a degree-4 vertex.
        if len(incoming) >= 4:
            candidate = 1 + sum(value for _, value in top4)
            if candidate > answer:
                answer = candidate

        # Use v as a leaf; its neighbor-side structure must contain
        # at least one degree-4 vertex.
        best_branch_neighbor = -1
        if parent[v] != -1:
            best_branch_neighbor = max(best_branch_neighbor, up_branch[v])
        for u in graph[v]:
            if parent[u] == v:
                best_branch_neighbor = max(best_branch_neighbor, down_branch[u])

        if best_branch_neighbor != -1:
            answer = max(answer, 1 + best_branch_neighbor)

        # Compute messages from v to each child.
        for child in graph[v]:
            if parent[child] != v:
                continue

            if len(incoming) - 1 >= 3:
                total = 0
                used = 0
                for node_id, value in top4:
                    if node_id != child and used < 3:
                        total += value
                        used += 1

                branch = 1 + total
                up_branch[child] = branch
                up_total[child] = branch
            else:
                up_branch[child] = -1
                up_total[child] = 1

    print(answer)


