class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        total = n * m
        g = [value for row in grid for value in row]

        # Clockwise directions in matrix coordinates:
        # southeast -> southwest -> northwest -> northeast
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # straight[d][i] = longest valid alternating segment starting at i
        # and moving in direction d.
        straight = [array('H', [0]) * total for _ in range(4)]

        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)

            dp = straight[d]
            for r in rows:
                base = r * m
                for c in cols:
                    idx = base + c
                    nr, nc = r + dr, c + dc

                    if 0 <= nr < n and 0 <= nc < m:
                        nxt = nr * m + nc
                        expected = 0 if g[idx] == 2 else 2
                        if g[nxt] == expected:
                            dp[idx] = dp[nxt] + 1
                        else:
                            dp[idx] = 1
                    else:
                        dp[idx] = 1

        # prefix[d][i] = longest valid segment ending at i, starting with 1,
        # and moving in direction d.
        prefix = [array('H', [0]) * total for _ in range(4)]

        for d, (dr, dc) in enumerate(dirs):
            rows = range(n) if dr == 1 else range(n - 1, -1, -1)
            cols = range(m) if dc == 1 else range(m - 1, -1, -1)

            dp = prefix[d]
            for r in rows:
                base = r * m
                for c in cols:
                    idx = base + c
                    value = g[idx]

                    if value == 1:
                        dp[idx] = 1
                        continue

                    pr, pc = r - dr, c - dc
                    if 0 <= pr < n and 0 <= pc < m:
                        prev = pr * m + pc
                        expected = 0 if g[prev] == 2 else 2
                        if dp[prev] and value == expected:
                            dp[idx] = dp[prev] + 1

        answer = 0

        for r in range(n):
            base = r * m
            for c in range(m):
                idx = base + c

                if g[idx] == 1:
                    for d in range(4):
                        if straight[d][idx] > answer:
                            answer = straight[d][idx]

                for d, (dr, dc) in enumerate(dirs):
                    length_before_turn = prefix[d][idx]
                    if not length_before_turn:
                        continue

                    clockwise = (d + 1) % 4
                    cdr, cdc = dirs[clockwise]
                    nr, nc = r + cdr, c + cdc

                    if 0 <= nr < n and 0 <= nc < m:
                        nxt = nr * m + nc
                        expected = 0 if g[idx] == 2 else 2
                        if g[nxt] == expected:
                            candidate = length_before_turn + straight[clockwise][nxt]
                            if candidate > answer:
                                answer = candidate

        return answer

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split("*")

        def occurrences(pattern: str):
            m = len(pattern)
            if m == 0:
                return range(n + 1)

            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j > 0 and pattern[i] != pattern[j]:
                    j = pi[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                pi[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j > 0 and ch != pattern[j]:
                    j = pi[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]

            return result

        def next_occurrence(pattern: str):
            occ = occurrences(pattern)
            if not pattern:
                return None

            result = [n + 1] * (n + 1)
            j = len(occ) - 1
            current = n + 1

            for i in range(n, -1, -1):
                if j >= 0 and occ[j] == i:
                    current = occ[j]
                    j -= 1
                result[i] = current

            return result

        occ_a = occurrences(a)
        next_b = next_occurrence(b)
        next_c = next_occurrence(c)

        la, lb, lc = len(a), len(b), len(c)
        best = n + 1

        for start in occ_a:
            end_a = start + la

            if lb == 0:
                start_b = end_a
            else:
                start_b = next_b[end_a]
                if start_b > n:
                    continue

            end_b = start_b + lb

            if lc == 0:
                start_c = end_b
            else:
                start_c = next_c[end_b]
                if start_c > n:
                    continue

            best = min(best, start_c + lc - start)

        return -1 if best == n + 1 else best

