def factorize(x):
    res = {}
    d = 2
    while d * d <= x:
        while x % d == 0:
            res[d] = res.get(d, 0) + 1
            x //= d
        d += 1
    if x > 1:
        res[x] = res.get(x, 0) + 1
    return res


def solve_prime(p, exponents, n):
    total = sum(exponents)
    if total == 0:
        return 1

    weights = [1] * (total + 1)
    for h in range(1, total + 1):
        weights[h] = weights[h - 1] * p % MOD

    touched = [0] * (total + 1)
    untouched = weights[:]
    untouched[0] = 0
    touched[0] = 1

    for step in exponents:
        new_touched = [0] * (total + 1)
        new_untouched = [0] * (total + 1)

        if step == 0:
            for h in range(total + 1):
                t = touched[h]
                u = untouched[h]
                if h == 0:
                    new_touched[h] = t
                else:
                    new_touched[h] = t * weights[h] % MOD
                    new_untouched[h] = u * weights[h] % MOD
        else:
            for h in range(total + 1):
                t = touched[h]
                u = untouched[h]

                d = h + step
                if d <= total:
                    w = weights[d]
                    if t:
                        new_touched[d] = (new_touched[d] + t * w) % MOD
                    if u:
                        new_untouched[d] = (new_untouched[d] + u * w) % MOD

                d = h - step
                if d >= 0:
                    if d == 0:
                        if t:
                            new_touched[0] = (new_touched[0] + t) % MOD
                        if u:
                            new_touched[0] = (new_touched[0] + u) % MOD
                    else:
                        w = weights[d]
                        if t:
                            new_touched[d] = (new_touched[d] + t * w) % MOD
                        if u:
                            new_untouched[d] = (new_untouched[d] + u * w) % MOD

        touched = new_touched
        untouched = new_untouched

    return sum(touched) % MOD


def main():
    input = sys.stdin.readline
    n = int(input())
    a = list(map(int, input().split()))

    factorizations = [factorize(x) for x in a]
    primes = set()
    for f in factorizations:
        primes.update(f.keys())

    answer = 1

    for p in primes:
        exponents = [f.get(p, 0) for f in factorizations]
        answer = answer * solve_prime(p, exponents, n) % MOD

    print(answer)


