from typing import List
from math import gcd


class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        m = len(target)
        full = (1 << m) - 1

        lcms = [1] * (1 << m)
        for mask in range(1, 1 << m):
            bit = mask & -mask
            idx = bit.bit_length() - 1
            prev = mask ^ bit
            lcms[mask] = lcms[prev] // gcd(lcms[prev], target[idx]) * target[idx]

        submasks = [[] for _ in range(1 << m)]
        for mask in range(1 << m):
            sub = mask
            while sub:
                submasks[mask].append(sub)
                sub = (sub - 1) & mask

        inf = 10**30
        dp = [inf] * (1 << m)
        dp[0] = 0

        for num in nums:
            costs = [0] * (1 << m)
            for mask in range(1, 1 << m):
                multiple = ((num + lcms[mask] - 1) // lcms[mask]) * lcms[mask]
                costs[mask] = multiple - num

            new_dp = dp[:]

            for mask, current in enumerate(dp):
                if current == inf:
                    continue

                remaining = full ^ mask
                for sub in submasks[remaining]:
                    next_mask = mask | sub
                    candidate = current + costs[sub]
                    if candidate < new_dp[next_mask]:
                        new_dp[next_mask] = candidate

            dp = new_dp
            if dp[full] == 0:
                return 0

        return dp[full]

