                for c in chars:
                    cur = [0] * (N + 1)
                    for j in range(N):
                        if S[j] == c:
                            cur[j + 1] = max(row[j + 1], cur[j], row[j] + 1)
                        else:
                            cur[j + 1] = max(row[j + 1], cur[j])
                    generated.append(tuple(cur))
                outcomes = tuple(generated)
                transition_cache[row] = outcomes

            for nxt in outcomes:
                ndp[nxt] = (ndp.get(nxt, 0) + value) % MOD

        dp = ndp

    answer = [0] * (N + 1)
    for row, value in dp.items():
        answer[row[-1]] = (answer[row[-1]] + value) % MOD

    print(*answer)

if __name__ == "__main__":
    main()

