import math

def sieve(limit):
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    primes = []
    for i in range(2, limit + 1):
        if is_prime[i]:
            primes.append(i)
            if i * i <= limit:
                for j in range(i * i, limit + 1, i):
                    is_prime[j] = False
    return primes

primes = sieve(31623)
factor_cache = {}

def factorize(n):
    if n in factor_cache:
        return factor_cache[n]
    original = n
    factors = []
    for p in primes:
        if p * p > n:
            break
        if n % p == 0:
            e = 0
            while n % p == 0:
                n //= p
                e += 1
            factors.append((p, e))
        if n == 1:
            break
    if n > 1:
        factors.append((n, 1))
    factor_cache[original] = factors
    return factors

def crt_pair(x, m, a, mod):
    t = ((a - x) % mod) * pow(m % mod, -1, mod) % mod
    return x + m * t, m * mod

def construct(n):
    if n == 1:
        return 1, 1

    factors = factorize(n)
    two_exp = 0
    odd_factors = []

    for p, e in factors:
        if p == 2:
            two_exp = e
        else:
            odd_factors.append((p, e))

    x = 0
    m = 1

    if two_exp >= 2 or (two_exp == 1 and not odd_factors):
        mod2 = 1 << (two_exp + 2)
        x, m = crt_pair(x, m, 3, mod2)

    if two_exp == 1 and odd_factors:
        p, e = odd_factors[0]
        mod = p ** (e + 1)
        residue = (-(1 + p)) % mod
        x, m = crt_pair(x, m, residue, mod)
        odd_factors = odd_factors[1:]

    for p, e in odd_factors:
        mod = p ** (e + 1)
        residue = 1 + p
        x, m = crt_pair(x, m, residue, mod)

    if x == 0:
        x = m

    return x, m

