    main()

from typing import List


class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def calculate(is_max: bool) -> int:
            left = [-1] * n
            right = [n] * n

            stack = []

            # Previous strictly greater/smaller element
            for i, value in enumerate(nums):
                if is_max:
                    while stack and nums[stack[-1]] <= value:
                        stack.pop()
                else:
                    while stack and nums[stack[-1]] >= value:
                        stack.pop()

                if stack:
                    left[i] = stack[-1]
                stack.append(i)

            stack = []

            # Next greater-or-equal/smaller-or-equal element
            for i in range(n - 1, -1, -1):
                value = nums[i]

                if is_max:
                    while stack and nums[stack[-1]] < value:
                        stack.pop()
                else:
                    while stack and nums[stack[-1]] > value:
                        stack.pop()

                if stack:
                    right[i] = stack[-1]
                stack.append(i)

            total = 0
            limit = k + 1

            for i, value in enumerate(nums):
                left_choices = i - left[i]
                right_choices = right[i] - i

                max_left = min(left_choices, k)

                # Count pairs (a, b) such that:
                # 1 <= a <= left_choices
                # 1 <= b <= right_choices
                # a + b <= k + 1
                full_right = min(max_left, max(0, limit - right_choices))

                count = full_right * right_choices

                remaining = max_left - full_right
                count += (
                    remaining * limit
                    - (full_right + 1 + max_left) * remaining // 2
                )

                total += value * count

            return total

        return calculate(True) + calculate(False)

import sys

def solve():
    N, MOD = map(int, sys.stdin.readline().split())

    E = N * (N - 1) // 2

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (N + 1)
    invfact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    values = []

    for x in range(E + 1):
        q = (x + 1) % MOD

        qp = [1] * (N + 1)
        for i in range(1, N + 1):
            qp[i] = qp[i - 1] * q % MOD

        trans = [[0] * (N + 1) for _ in range(N + 1)]
        for a in range(1, N + 1):
            qa_minus_one = (qp[a] - 1) % MOD
            for b in range(1, N + 1):
                w = pow(qa_minus_one, b, MOD)
                w = w * qp[b * (b - 1) // 2] % MOD
                w = w * invfact[b] % MOD
                trans[a][b] = w

        # dp[t][parity][last_size] is a dictionary: difference -> count
        dp = [
            [
                [dict() for _ in range(N + 1)]
                for _ in range(2)
            ]
            for _ in range(N + 1)
        ]

        # Root is the only vertex in layer 0.
        dp[1][0][1][1] = 1

        answer = 0

        for t in range(1, N):
            remaining = N - t
            for layer_parity in range(2):
                sign = -1 if layer_parity == 0 else 1
                for last in range(1, t + 1):
                    cur = dp[t][layer_parity][last]
                    if not cur:
                        continue

                    max_b = remaining
                    for diff, val in cur.items():
                        for b in range(1, max_b + 1):
                            nt = t + b
                            nd = diff + sign * b
                            rem = N - nt

                            # Necessary conditions for eventually reaching difference 0.
                            if abs(nd) > rem or ((nd - rem) & 1):
                                continue

                            w = trans[last][b]
                            add = val * w % MOD

                            if nt == N:
                                if nd == 0:
                                    answer += add
                                    if answer >= MOD:
                                        answer -= MOD
                            else:
                                target = dp[nt][layer_parity ^ 1][b]
                                target[nd] = (target.get(nd, 0) + add) % MOD

        answer = answer * fact[N - 1] % MOD
        values.append(answer)

    # Convert values at x = 0,1,...,E to ordinary polynomial coefficients.
    # First obtain Newton coefficients.
    diff = values[:]
    newton = [0] * (E + 1)
    inv = [1] * (E + 1)
    for i in range(1, E + 1):
        inv[i] = pow(i, MOD - 2, MOD)

    for k in range(E + 1):
        newton[k] = diff[0] * invfact[k] % MOD
        for i in range(E - k):
            diff[i] = (diff[i + 1] - diff[i]) % MOD

    # Convert Newton basis to power basis.
    coeff = [0] * (E + 1)
    basis = [1]

    for k in range(E + 1):
        c = newton[k]
        for i, v in enumerate(basis):
            coeff[i] = (coeff[i] + c * v) % MOD

        if k == E:
            break

        nb = [0] * (len(basis) + 1)
        for i, v in enumerate(basis):
            nb[i] = (nb[i] - v * k) % MOD
            nb[i + 1] = (nb[i + 1] + v) % MOD
        basis = nb

    print(*coeff[N - 1:E + 1])

if __name__ == "__main__":
    solve()

