import sys


def matmul(a, b, mod):
    n = len(a)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        ri = res[i]
        ai = a[i]
        for k, x in enumerate(ai):
            if x:
                bk = b[k]
                for j in range(n):
                    ri[j] += x * bk[j]
        for j in range(n):
            ri[j] %= mod
    return res


def matpow(a, e, mod):
    n = len(a)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1

    while e:
        if e & 1:
            res = matmul(res, a, mod)
        a = matmul(a, a, mod)
        e >>= 1
    return res


def main():
    input = sys.stdin.readline
    n, p = map(int, input().split())
    a = [list(map(int, input().split())) for _ in range(n)]

    if p == 2:
        # There is only one possible replacement: every zero becomes 1.
        b = [[1 if a[i][j] == 0 else a[i][j] for j in range(n)]
             for i in range(n)]
        ans = matmul(b, b, 2)
        for row in ans:
            print(*row)
        return

    zero_count = sum(a[i][j] == 0 for i in range(n) for j in range(n))

    # C contains only the fixed, nonzero entries.
    c = [[a[i][j] if a[i][j] != 0 else 0 for j in range(n)]
         for i in range(n)]

    ans = matpow(c, p, p)
    correction = [[0] * n for _ in range(n)]

    # A zero entry can contribute only if it is used p-1 times.
    # For p >= 5, this forces the zero entry to be a diagonal entry.
    for u in range(n):
        if a[u][u] != 0:
            continue

        for x in range(n):
            if x != u and c[x][u]:
                correction[x][u] = (correction[x][u] + c[x][u]) % p

        for y in range(n):
            if y != u and c[u][y]:
                correction[u][y] = (correction[u][y] + c[u][y]) % p

    if p == 3:
        # For p=3, a non-diagonal zero edge may occur twice,
        # with the reverse fixed edge occurring once.
        for u in range(n):
            for v in range(n):
                if u != v and a[u][v] == 0 and c[v][u]:
                    w = c[v][u]
                    correction[u][v] = (correction[u][v] + w) % p
                    correction[v][u] = (correction[v][u] + w) % p

    sign = 1 if zero_count % 2 == 0 else p - 1

    for i in range(n):
        for j in range(n):
            ans[i][j] = sign * (ans[i][j] + correction[i][j]) % p

    for row in ans:
        print(*row)


if __name__ == "__main__":
    main()

class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7
        unequal = n - 1 - k
        return (
            m
            * pow(m - 1, unequal, MOD)
            * __import__("math").comb(n - 1, k)
        ) % MOD

