import sys


def solve():
    input = sys.stdin.readline
    n = int(input())

    buildings = [tuple(map(int, input().split())) for _ in range(n)]

    hull = []
    best_num = None
    best_den = 1

    for x, h in buildings:
        if hull:
            lo, hi = 0, len(hull) - 1

            while lo < hi:
                mid = (lo + hi) // 2
                xm, hm = hull[mid]
                xn, hn = hull[mid + 1]

                # Slope(current -> hull[mid]) <= slope(current -> hull[mid+1])
                left = (h - hm) * (x - xn)
                right = (h - hn) * (x - xm)

                if left <= right:
                    hi = mid
                else:
                    lo = mid + 1

            a, b = hull[lo]
            num = x * b - a * h
            den = x - a

            if best_num is None or num * best_den > best_num * den:
                best_num = num
                best_den = den

        while len(hull) >= 2:
            x1, h1 = hull[-2]
            x2, h2 = hull[-1]

            cross = (x2 - x1) * (h - h1) - (h2 - h1) * (x - x1)

            if cross >= 0:
                hull.pop()
            else:
                break

        hull.append((x, h))

    if best_num is None or best_num < 0:
        print(-1)
    else:
        print(f"{best_num / best_den:.18f}")


