def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    total_sum = sum(a)
    answer = (n + 1) * total_sum

    max_sum = 2 * max(a)
    max_k = max_sum.bit_length()

    for k in range(1, max_k):
        mask = (1 << k) - 1
        modulus = 1 << k

        counts = {}
        sums = {}

        for x in a:
            r = x & mask
            counts[r] = counts.get(r, 0) + 1
            sums[r] = sums.get(r, 0) + x

        divisible_sum = 0

        for r, c in counts.items():
            q = (-r) & mask

            if r > q:
                continue

            sr = sums[r]

            if r == q:
                divisible_sum += (c + 1) * sr
            else:
                cq = counts.get(q)
                if cq is not None:
                    divisible_sum += cq * sr + c * sums[q]

        answer -= divisible_sum // modulus

    print(answer)

