import sys
from bisect import bisect_left


def build_sequence(has_ball, perm, x):
    n = len(perm)
    inv = [0] * n
    for i, v in enumerate(perm):
        inv[v] = i

    in_cycle = [False] * n
    cur = x
    while not in_cycle[cur]:
        in_cycle[cur] = True
        cur = perm[cur]

    for i in range(n):
        if has_ball[i] and not in_cycle[i]:
            return None

    dist = [-1] * n
    cur = inv[x]
    d = 1
    while cur != x:
        dist[cur] = d
        cur = inv[cur]
        d += 1

    max_dist = 0
    for i in range(n):
        if has_ball[i] and dist[i] > max_dist:
            max_dist = dist[i]

    seq = []
    cur = x
    for _ in range(max_dist):
        cur = inv[cur]
        seq.append(cur)

    return seq


def lcs_unique(a, b):
    if not a or not b:
        return 0

    pos = {v: i for i, v in enumerate(a)}
    mapped = [pos[v] for v in b if v in pos]

    tails = []
    for v in mapped:
        i = bisect_left(tails, v)
        if i == len(tails):
            tails.append(v)
        else:
            tails[i] = v
    return len(tails)


