import sys


def main():
    input = sys.stdin.buffer.readline
    n = int(input())
    a = list(map(int, input().split()))

    size = 1
    while size < n:
        size <<= 1

    seg = [0] * (size << 1)
    seg[size:size + n] = a
    for i in range(size - 1, 0, -1):
        seg[i] = max(seg[i << 1], seg[i << 1 | 1])

    def first_ge(start, value):
        if start >= n:
            return -1

        p = start + size
        while True:
            while (p & 1) == 0:
                p >>= 1
            if seg[p] >= value:
                while p < size:
                    left = p << 1
                    if seg[left] >= value:
                        p = left
                    else:
                        p = left | 1
                return p - size
            p += 1
            if (p & -p) == p:
                return -1

    def last_ge(end, value):
        if end <= 0:
            return -1

        p = end + size
        while True:
            p -= 1
            while p > 1 and (p & 1):
                p >>= 1
            if seg[p] >= value:
                while p < size:
                    right = p << 1 | 1
                    if seg[right] >= value:
                        p = right
                    else:
                        p <<= 1
                return p - size
            if (p & -p) == p:
                return -1

    prefix = [0] * (n + 1)
    for i, value in enumerate(a):
        prefix[i + 1] = prefix[i] + value

    ans = [0] * n

    for start in range(n):
        left = right = start
        total = a[start]

        while True:
            old_total = total

            blocker_left = last_ge(left, total)
            if blocker_left == -1:
                if left > 0:
                    total += prefix[left]
                    left = 0
            elif blocker_left + 1 < left:
                total += prefix[left] - prefix[blocker_left + 1]
                left = blocker_left + 1

            blocker_right = first_ge(right + 1, total)
            if blocker_right == -1:
                if right + 1 < n:
                    total += prefix[n] - prefix[right + 1]
                    right = n - 1
            elif blocker_right > right + 1:
                total += prefix[blocker_right] - prefix[right + 1]
                right = blocker_right - 1

            if total == old_total:
                break

        ans[start] = total

    print(*ans)


